"""The workbook's Dictionary sheet: every term in plant language.

Generated text, not typed: the numbers come from numbers.json (the `F` argument), so a
definition can't quote a stale WACC or share count. build_model.py writes it as the second sheet.
"""

TITLE = "Data dictionary — every term in this model, in plant language"
INTRO = "Three columns: what it is (the textbook), how this model computes it (the sheet), and what it means on the floor (the corrugator). Read down once; then it is a lookup."

def rows(F):
    """[(kind, cells)] where kind is "section", "head" or "term"."""
    return [
        ('section', ["THE INCOME SIDE"]),
        ('head', ["Term", "What it is", "How this model computes it", "What it means on the floor"]),
        ('term', ["Net sales (revenue)", "Dollars billed to customers in the period, net of discounts and freight allowances.", "Model row 'Net sales'. 2026E = H1 × 2 split by the 2025 NA/EMEA mix; 2027E = volume × price; 2028+ grows at the long-term rate.", "Tons of board × price per ton, plus the box plants' value-add. Every $10/ton on the index shows up here first."]),
        ('term', ["Adjusted EBITDA", "Earnings Before Interest, Taxes, Depreciation and Amortization, with one-time items (severance, deal costs) added back. The cash the operations throw off before the bank, the IRS, and the wearing-out of the mills.", "'Adj. EBITDA — enterprise' = NA + EMEA + corporate. 2026E = guidance midpoint; 2027E = the bridge; 2028+ = mid-cycle margin × revenue.", "What the machines earn. It is the number the plant manager can move: speed, trim, downtime, price. It is NOT cash — capex and interest come out of it."]),
        ('term', ["EBITDA margin", "EBITDA ÷ revenue.", "'margin' rows.", f"Cents of operating profit per dollar of board sold. PKG runs {F['pkg_margin']}, SW {F['sw_margin']}. A mill-integrated box business with good trim lives in between."]),
        ('term', ["The 2027 bridge", "A walk from one year's EBITDA to the next, one driver at a time, so each piece can be argued separately.", "'Adj. EBITDA — NA' 2027E = 2026 guide + price that sticks − what's already in + volume × contribution + cost-out − inflation.", "Same thing as a shift-to-shift variance: what changed, by cause, in dollars."]),
        ('term', ["Price that sticks", "The share of an announced/index-recognized price increase that is still in realized box prices a year later.", f"Inputs 'stick_pct' × {F['idx']}/ton × {F['sens1']} per $1/ton, minus the {F['in_guide']} already in 2026 guidance.", "Index-linked contracts lag months; buyers push back; a soft year gives some back. 'Half, lag is months' is the mid case."]),
        ('term', ["Contribution margin", "Profit on one more unit, before fixed costs.", f"Inputs 'contrib_margin' ({F['contrib']}) × incremental NA revenue from volume.", "The next ton through a mill that's already running: paper, starch, energy and freight cost money; the machine and the crew don't cost more."]),
        ('term', ["Mid-cycle margin", "The margin a cyclical business earns on average across a full up-and-down cycle, not at the peak or the trough.", f"Inputs 'midcycle_na_margin' ({F['na_margin']}) applied from 2028E. Deliberately BELOW the 2027 price-spike year.", "Containerboard has a cycle: capacity out → price up → capacity back/demand down → price down. Valuing a cyclical at its best year is how people lose money on it."]),
        ('term', ["Corporate / other", "Head-office cost not allocated to segments.", "Enterprise guidance − segment guidance; held flat.", "The building in Memphis."]),
        ('section', ["FROM PROFIT TO CASH"]),
        ('head', ["Term", "What it is", "How this model computes it", "What it means on the floor"]),
        ('term', ["D&A (depreciation & amortization)", "The accounting charge that spreads the cost of mills and machines over their lives. Non-cash in the year it's booked.", f"'Depreciation & amortization' = 2026 guidance ({F['da26']}), then {F['da_pct']} of revenue.", "A paper machine costs hundreds of millions and runs for decades; D&A is that cost showing up a slice at a time. It is the reason EBITDA overstates what you can keep."]),
        ('term', ["EBIT", "Earnings before interest and taxes = EBITDA − D&A. Operating profit after the wearing-out of assets.", "'EBIT (adjusted)'.", "What the operation earns after paying for the fact that the mills are getting older."]),
        ('term', ["NOPAT", "Net Operating Profit After Tax = EBIT × (1 − tax rate). Operating profit as if the company had no debt.", "'NOPAT'.", "The profit the business would make with no bank involved. Used so that financing is handled separately in the discount rate."]),
        ('term', ["Capital expenditures (capex)", "Cash spent on long-lived assets: new machines, rebuilds, conversions, greenfield plants.", f"2026E = H1 × 2 ({F['capex26_b']}); 2027E input; 2028+ = {F['capex_pct']} of revenue.", "Riverdale #16 conversion, the $225M Mississippi box plant, every dryer rebuild. 'Assets that are expensive to run' lives in this row."]),
        ('term', ["Maintenance vs growth capex", "Maintenance keeps today's capacity running; growth adds capacity or capability.", f"Not split in the model; the 2028+ {F['capex_pct']} assumes transformation capex rolls off toward maintenance.", "Rebuilding a corrugator's single-facer is maintenance; a new machine is growth. The P&L can't tell them apart; the floor can."]),
        ('term', ["Net working capital (NWC)", "Inventory + receivables − payables: cash tied up in running the business.", f"'Investment in NWC' = {F['nwc_pct']} × change in revenue.", "Rolls in the warehouse, boxes shipped but unpaid, paper bought on terms. Growing sales soaks up cash here before it shows up as profit."]),
        ('term', ["Unlevered free cash flow (UFCF)", "Cash available to ALL capital providers (debt and equity) after taxes, capex and working capital, before interest. NOPAT + D&A − capex − ΔNWC.", "'Unlevered free cash flow' (also subtracts the one-time separation cash).", "The cash left after you've paid to keep the mills alive. This is what a DCF discounts — not EBITDA, not profit."]),
        ('term', ["Levered free cash flow", "UFCF minus after-tax interest: cash for shareholders only.", f"Sanity row 'Levered FCF proxy'. 2026E ≈ {F['lfcf26_100']} vs the company's $300–500M guide; 2025 actual was {F['fcf25']}.", f"What's left to pay the dividend ({F['div_cost']}/yr). When this row is smaller than the dividend, the yield is a warning, not a gift."]),
        ('section', ["THE DISCOUNTING"]),
        ('head', ["Term", "What it is", "How this model computes it", "What it means on the floor"]),
        ('term', ["Discount rate / WACC", "Weighted Average Cost of Capital: the blended return that lenders and shareholders require, weighted by how much of the company each funds. Used to turn future cash into today's dollars.", f"DCF rows: cost of equity = risk-free + β × ERP; after-tax cost of debt = kd × (1 − t); WACC = weights × each. ≈ {F['wacc']}.", f"The hurdle rate. A dollar of cash flow three years out is worth 1/({F['wacc_1p']})^3 ≈ {F['df3']} today. Raising WACC 1 point knocks ~{F['wacc_plus1']} off the value; it is the most-argued number in finance."]),
        ('term', ["Risk-free rate", "The yield on a government bond: what you earn for taking no credit risk.", f"Inputs 'rf' (10-yr Treasury, ~{F['rf']}).", "The alternative to everything."]),
        ('term', ["Beta (β)", "How much the stock moves relative to the market. 1.0 = with the market; 1.1 = 10% more.", f"Inputs 'beta' ({F['beta']}).", "Cyclicals have betas above 1 because the whole economy shows up in box demand."]),
        ('term', ["Equity risk premium (ERP)", "The extra return investors demand for owning stocks instead of government bonds.", f"Inputs 'erp' ({F['erp']}). Damodaran publishes the implied ERP monthly.", f"Why cost of equity (~{F['coe']}) is above the bond yield (~{F['rf']})."]),
        ('term', ["Cost of debt", "The interest rate the company pays on new borrowing, after tax (interest is deductible).", f"Inputs 'kd' ({F['kd']}) × (1 − {F['tax']}).", "IP's bonds trade around 5–6%; BBB-ish credit."]),
        ('term', ["Present value (PV) / discount factor", "Today's worth of a future amount: amount ÷ (1 + WACC)^years.", "'Discount factor' and 'Present value of UFCF' rows; mid-year timing from Oct 2026.", "Same math as a lease or a loan, run backwards."]),
        ('term', ["Terminal value (TV)", "The value of all cash flows beyond the explicit forecast, collapsed into one number at the end of the forecast.", "Average of the two methods below; its PV is 'PV of terminal value'.", f"Most of the answer. The model shows TV as % of EV (≈{F['tv_share']}) on purpose: whatever you assume about year 2031+ IS the valuation."]),
        ('term', ["Gordon growth (perpetuity) method", "TV = next year's cash flow ÷ (WACC − g). Assumes cash flow grows at g forever.", f"'Gordon growth' row; g = {F['g']}.", "Only valid if g < WACC and the business is steady-state. The implied exit multiple is printed next to it as a check."]),
        ('term', ["Exit multiple method", "TV = final-year EBITDA × a multiple peers trade at.", f"'Exit multiple' row; {F['exit_mult']} (SW {F['sw_mult']}, PKG {F['pkg_mult']}).", "'What would a buyer pay for this business in 2030?' The implied perpetual growth is printed as the reverse check."]),
        ('term', ["Enterprise value (EV)", "Value of the whole operating business to all capital providers = PV of cash flows + PV of terminal value. Also = market cap + net debt.", f"'Enterprise value' (model) and 'market EV' = {F['mcap_b']} + {F['net_debt_b']} ≈ {F['ev_mkt_b']} (today).", "The price of the mills and plants as a going concern, regardless of who funded them."]),
        ('term', ["Net debt", "Debt minus cash. Plus 'debt-like' items (pension deficits, leases) when material.", f"Inputs: {F['gross_debt']} − {F['cash']} = {F['net_debt']}. The 10-K's debt-like items ({F['debt_like']} after tax: pension deficits, retiree medical, the 2027 timber tax net of the notes) come off the equity value, not the WACC weights.", f"What the equity holder owes before owning anything. {F['net_debt_b']} against {F['mcap_b0']} of market cap is a real amount."]),
        ('term', ["Equity value / value per share", "EV − net debt = equity value; ÷ diluted shares = per share.", f"'Equity value' and 'Value per share'; {F['shares']} shares.", f"The number you compare to {F['price']}."]),
        ('term', ["EV/EBITDA multiple", "Enterprise value ÷ EBITDA. The most common comparison across companies because it ignores financing and D&A differences.", f"Comps: PKG {F['pkg_mult']}, SW {F['sw_mult']}, IP {F['mkt_ev_26']} (2026E) and ~{F['mkt_ev_27']} (2027E bridge) at {F['price']}.", f"'Years of operating cash to buy the business.' The market paying {F['mkt_ev_26']} for IP and {F['pkg_mult']} for PKG is a statement about trust in the margins."]),
        ('term', ["Sum of the parts (SOTP)", "Value each segment at its own multiple, add them, subtract net debt. Used when the parts could be separated or sold.", f"Comps_SOTP: NA 2028E × {F['sotp_na_mult1']} + EMEA × {F['sotp_emea_mult']} − debt − separation costs ≈ {F['sotp_ps']}/share; plus the EMEA multiple at which SOTP = {F['price']}.", "Live question since Oct 15: DS Smith is for sale or spin. If a buyer pays more than the breakeven multiple, the market is underpricing the sum."]),
        ('section', ["THE BET"]),
        ('head', ["Term", "What it is", "How this model computes it", "What it means on the floor"]),
        ('term', ["Scenario", "One complete, internally consistent story with numbers attached (Bear / Mid-cycle / Bull).", f"Scenarios sheet: ten levers per column, same chain; weights {F['weights']}.", "'What if the cycle turns' is a scenario; 'what if margin is 1 point higher' is a sensitivity."]),
        ('term', ["Sensitivity table", "Value as a function of two assumptions, holding everything else fixed.", "Sensitivity sheet: NA mid-cycle margin × exit multiple; and 2027 EBITDA vs price that sticks.", "A map of what you'd have to believe to get a given number."]),
        ('term', ["Monte Carlo", "Draw the uncertain assumptions from distributions many times, run the model each time, look at the distribution of answers.", f"montecarlo.py: {F['n_runs']} runs, same chain as the Scenarios sheet.", f"The point estimate ({F['dcf_ps']}) becomes P(value > {F['price']}) = {F['p_above']} with a 10th percentile of {F['p10']}. A bet needs the second form."]),
        ('term', ["Regime / correlation", "In a downturn the inputs move together: price doesn't stick, demand falls, margins and multiples compress at once. Drawing them independently understates the tails.", f"montecarlo.py draws the cycle first (P = {F['p_down']}), then every assumption conditional on it.", "Why the first Monte Carlo said 90% and was wrong. The histogram's two humps are the two regimes."]),
        ('term', ["Model risk", "The chance the model's structure — not its inputs — is wrong.", f"{F['noise']} lognormal noise on the terminal value.", "Damodaran's margin of safety, made explicit instead of applied at the end."]),
        ('term', ["Expected value / median / percentiles", "Mean of the outcomes; the middle outcome; the value below which 10% (90%) of outcomes fall.", f"mc.json: mean {F['mean']}, median {F['median']}, 10th {F['p10']}, 90th {F['p90']}.", "The 10th percentile is the number to size against, not the mean."]),
        ('term', ["Breakeven cycle probability", "The P(down-cycle) at which the expected value equals the price.", f"mc_pdown.json: ≈ {F['fair_odds']}.", f"What the market is 'saying' at {F['price']}: a coin flip on the cycle. Your edge is whether you can call it better than a coin."]),
        ('term', ["Kelly criterion", "The fraction of capital that maximizes long-run growth given a known payoff distribution: f* = argmax E[log(1 + f·r)].", f"montecarlo.py: numeric Kelly ≈ {F['kelly']}; half-Kelly {F['half_kelly']}.", f"Assumes you KNOW the distribution. You don't; you assigned the {F['p_down']}. Treat it as a ceiling, then divide by the number of things you could be wrong about. For one cyclical stock: small."]),
        ('term', ["Margin of safety", "Buy below your estimate of value by enough to be wrong and still be fine.", f"Mid-case {F['dcf_ps']} vs {F['price']} ≈ {F['margin_of_safety']} — modest for a cyclical with uncovered dividend; the Monte Carlo's 10th percentile ({F['p10']}) is the honest version.", "The same instinct as leaving a half-inch of trim rather than running the chute at 7.0."]),
    ]
